from itertools import combinations

# We need to partition {1, 2, ..., 24} into 4 subsets each summing to 75
# Let's use a constraint-based approach

def solve_partition():
    n = 24
    target = 75
    nums = list(range(1, n+1))

    # Use backtracking with constraint propagation
    # assignment[i] = which subset (0-3) number i+1 belongs to
    assignment = [-1] * n
    subset_sums = [0] * 4

    def backtrack(idx):
        if idx == n:
            return all(s == target for s in subset_sums)

        num = nums[idx]
        for subset in range(4):
            if subset_sums[subset] + num <= target:
                assignment[idx] = subset
                subset_sums[subset] += num
                if backtrack(idx + 1):
                    return True
                subset_sums[subset] -= num
                assignment[idx] = -1

        return False

    if backtrack(0):
        return assignment
    return None

result = solve_partition()
print("Result:", result)
if result:
    # Verify
    subsets = [[] for _ in range(4)]
    for i, s in enumerate(result):
        subsets[s].append(i+1)
    for i, sub in enumerate(subsets):
        print(f"Subset {i}: {sub}, sum = {sum(sub)}")
